<?php
session_start();require_once '../shared/config.php';requireLogin('customer','login.php');$db=getDB();
$stmt=$db->prepare("SELECT o.*,i.name item_name,i.image_path,v.store_name FROM orders o JOIN items i ON o.item_id=i.id JOIN vendors v ON o.vendor_id=v.id WHERE o.customer_id=? ORDER BY o.created_at DESC");$stmt->execute([$_SESSION['customer_id']]);$orders=$stmt->fetchAll();

$trustByOrder=[];
if($orders){
  $orderIds=array_column($orders,'id');$placeholders=implode(',',array_fill(0,count($orderIds),'?'));
  $trustStmt=$db->prepare("SELECT cr.rental_order_id,cr.inspection_type,cr.condition_score,cr.created_at
      FROM condition_reports cr JOIN orders o ON o.id=cr.rental_order_id
      WHERE o.customer_id=? AND cr.rental_order_id IN ($placeholders)
      ORDER BY cr.created_at DESC");
  $trustStmt->execute(array_merge([$_SESSION['customer_id']],$orderIds));
  foreach($trustStmt->fetchAll() as $tr){$oid=(int)$tr['rental_order_id'];$type=$tr['inspection_type'];if(!isset($trustByOrder[$oid]))$trustByOrder[$oid]=[];if(!isset($trustByOrder[$oid][$type]))$trustByOrder[$oid][$type]=$tr;}

  $sanStmt=$db->prepare("SELECT sr.rental_order_id,sr.status,sr.completed_at,sr.created_at
      FROM sanitization_records sr JOIN orders o ON o.id=sr.rental_order_id
      WHERE o.customer_id=? AND sr.rental_order_id IN ($placeholders)
      ORDER BY sr.created_at DESC");
  $sanStmt->execute(array_merge([$_SESSION['customer_id']],$orderIds));
  foreach($sanStmt->fetchAll() as $sr){$oid=(int)$sr['rental_order_id'];if(!isset($trustByOrder[$oid]))$trustByOrder[$oid]=[];if(!isset($trustByOrder[$oid]['sanitization']))$trustByOrder[$oid]['sanitization']=$sr;}
}
$buyStmt=$db->prepare("SELECT po.*,poi.item_id,poi.quantity,poi.unit_price,poi.total_price,i.name item_name,i.image_path,v.store_name
    FROM purchase_orders po
    JOIN purchase_order_items poi ON poi.order_id=po.id
    JOIN items i ON i.id=poi.item_id
    LEFT JOIN vendors v ON v.id=po.vendor_id
    WHERE po.customer_id=? ORDER BY po.created_at DESC");
$buyStmt->execute([$_SESSION['customer_id']]);$buyOrders=$buyStmt->fetchAll();
$labels=['new'=>'⏳ New Order','in_progress'=>'🚀 In Progress / Rented','completed'=>'✅ Completed / Returned'];
$buySteps=['confirmed'=>'Confirmed','packed'=>'Packed','shipped'=>'Shipped','delivered'=>'Delivered'];
$sellPurchaseStmt=$db->prepare("SELECT spo.*,sl.title,sl.image_path,c.name seller_name FROM seller_purchase_orders spo JOIN seller_listings sl ON sl.id=spo.listing_id JOIN customers c ON c.id=spo.seller_id WHERE spo.buyer_id=? ORDER BY spo.created_at DESC");
$sellPurchaseStmt->execute([$_SESSION['customer_id']]);$sellPurchases=$sellPurchaseStmt->fetchAll();
