<div class="foot"><div>Purchase Total: <b style="color:#8B1A1A">₹<?=number_format($o['total_price'],0)?></b></div><div>Order Status: <b><?=htmlspecialchars(ucfirst($o['order_status']))?></b></div></div></div>
